#!/usr/bin/env python3
from pathlib import Path
import base64,zlib,runpy,re

runpy.run_path("ci/generate_chatgpt_webview_v47_cross_surface_receipt.py", run_name="__main__")
ROOT=Path("runtime_probes/chatgpt-webview-stable-probe")
PKG=ROOT/"app/src/main/java/com/homayounisaghar/chatgptwebviewprobe"
BLOB=''
src=zlib.decompress(base64.b64decode(BLOB)).decode("utf-8")
(PKG/"OrchestratorPaidModelEffortTransactionalReceiptV48Activity.java").write_text(src)
# Telemetry config inherits v47 placeholders but gets an independent class configured by CI.
cfg47=(PKG/"TelemetryConfigV47.java").read_text()
cfg48=cfg47.replace("TelemetryConfigV47","TelemetryConfigV48")
(PKG/"TelemetryConfigV48.java").write_text(cfg48)
# Stable diagnostic package; monotonic update version.
g=ROOT/"app/build.gradle"
gs=g.read_text()
gs=re.sub(r"versionCode\s+48\b","versionCode 49",gs)
gs=gs.replace("0.45-stable-diag-cross-surface-light-receipt","0.46-stable-diag-transactional-light-receipt")
g.write_text(gs)
# Switch launcher to v48 class.
m=ROOT/"app/src/main/AndroidManifest.xml"
ms=m.read_text().replace("OrchestratorPaidModelEffortCrossSurfaceReceiptV47Activity","OrchestratorPaidModelEffortTransactionalReceiptV48Activity")
m.write_text(ms)
print("generated v0.46 transactional cross-surface receipt probe")
